#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────
# Claude Code status line · generated by Statusline Studio
# skin: custom · palette: Terracotta · shape: flow · lines: 3
# Claude Code pipes a JSON payload on stdin.
# ─────────────────────────────────────────────────────────────

# ---------- palette ----------
R=$'\033[0m'
C_fg=$'\033[38;2;230;232;238m'
C_dim=$'\033[38;2;107;114;128m'
C_muted=$'\033[38;2;154;161;177m'
C_accent=$'\033[38;2;232;132;107m'
C_good=$'\033[38;2;127;209;147m'
C_warn=$'\033[38;2;229;192;123m'
C_bad=$'\033[38;2;224;108;117m'
C_info=$'\033[38;2;124;171;232m'
C_special=$'\033[38;2;199;146;234m'

# ---------- heat ramp (green to red) ----------
RAMP=($'\033[38;2;63;212;127m' $'\033[38;2;92;217;111m' $'\033[38;2;142;222;92m' $'\033[38;2;194;224;79m' $'\033[38;2;232;209;63m' $'\033[38;2;240;176;58m' $'\033[38;2;240;138;53m' $'\033[38;2;236;99;48m' $'\033[38;2;229;68;46m' $'\033[38;2;224;32;32m')
pct_color(){ local p=${1%%.*}; [[ $p =~ ^-?[0-9]+$ ]] || p=0; [ "$p" -gt 100 ] && p=100; [ "$p" -lt 0 ] && p=0; printf %s "${RAMP[$(( p * 9 / 100 ))]}"; }
pct_color_inv(){ local p=${1%%.*}; [[ $p =~ ^-?[0-9]+$ ]] || p=0; pct_color $(( 100 - p )); }

# ---------- helpers ----------
cat_ne(){ local out="" a
  for a in "$@"; do [ -z "$a" ] && return; out+="$a"; done
  printf %s "$out"; }
bool_map(){ case "$1" in [Tt][Rr][Uu][Ee]) printf %s "$2" ;; *) printf %s "$3" ;; esac; }
basename_of(){ local p="${1//\\//}"; printf %s "${p##*/}"; }
# no index.lock, so git status never blocks Claude's own git work
export GIT_OPTIONAL_LOCKS=0
git_q(){ local b a o
  case "$1" in
    # symbolic-ref names the branch even before the first commit, where
    # rev-parse --abbrev-ref just prints "HEAD"; falls back to a short hash
    # when HEAD really is detached.
    branch)    git -C "$GD" symbolic-ref --quiet --short HEAD 2>/dev/null || git -C "$GD" rev-parse --short HEAD 2>/dev/null ;;
    hash)      git -C "$GD" log -1 --format=%h 2>/dev/null ;;
    ago)       git -C "$GD" log -1 --format=%cr 2>/dev/null | awk '{ u = substr($2,1,1); if ($2 ~ /^month/) u = "mo"; printf "%s%s", $1, u }' ;;
    msg)       git -C "$GD" log -1 --format=%s 2>/dev/null ;;
    tag)       git -C "$GD" describe --tags --abbrev=0 2>/dev/null ;;
    stash)     git -C "$GD" stash list 2>/dev/null | wc -l | tr -d ' ' ;;
    untracked) git -C "$GD" ls-files --others --exclude-standard 2>/dev/null | wc -l | tr -d ' ' ;;
    ahead)     if read -r b a < <(git -C "$GD" rev-list --left-right --count @{u}...HEAD 2>/dev/null); then
                 o=""; [ "${a:-0}" -gt 0 ] && o="↑$a"; [ "${b:-0}" -gt 0 ] && o="$o↓$b"; printf %s "$o"; fi ;;
  esac; }
git_dirty(){ local n
  git -C "$GD" rev-parse --git-dir >/dev/null 2>&1 || return
  n=$(git -C "$GD" status --porcelain 2>/dev/null | wc -l | tr -d ' ')
  case "$1" in
    dot)  if [ "$n" -gt 0 ]; then printf '●'; else printf '✓'; fi ;;
    star) [ "$n" -gt 0 ] && printf '*' ;;
    *)    [ "$n" -gt 0 ] && printf '✎%s' "$n" ;;
  esac; }
join_seg(){ local sep="$1"; shift; local out="" s sp=0
  for s in "$@"; do
    [ -z "$s" ] && continue
    if [ -z "${s// /}" ]; then out+="$s"; sp=1; continue; fi   # a spacer: no separator around it
    [ -n "$out" ] && [ "$sp" = "0" ] && out+="$sep"
    out+="$s"; sp=0
  done; printf %s "$out"; }
knum(){ awk -v n="$1" 'BEGIN{ n=n+0
  if(n>=999500) printf "%.1fM", int(n/100000+0.5)/10
  else if(n>=1000) printf "%dk", int(n/1000+0.5)
  else printf "%d", int(n) }'; }
time_left(){ local ts=${1%%.*} now left h m
  [ "$ts" -gt 0 ] 2>/dev/null || return
  now=$(date +%s); left=$(( ts - now ))
  [ "$left" -le 0 ] && { printf %s "now"; return; }
  h=$(( left / 3600 )); m=$(( (left % 3600) / 60 ))
  if [ "$h" -ge 24 ]; then printf "%dd%dh" $(( h / 24 )) $(( h % 24 ))
  elif [ "$h" -gt 0 ]; then printf "%dh%02dm" "$h" "$m"
  else printf "%dm" "$m"; fi; }
money(){ awk -v c="$1" -v f="$2" 'BEGIN{ if(c=="") exit
  c=c+0
  if(f=="cents") printf "%.0f¢", c*100; else if(f=="round") printf "$%.0f", c; else printf "$%.2f", c }'; }
# a Windows path is shortened by the Windows home and keeps its separators, as in Python and Node
# (~ comes from a variable: bash 3.2 keeps the backslash of \~ inside double quotes)
short_path(){ local h=$HOME p=$1 s t='~'
  case "$1" in [A-Za-z]:\\*) h=${USERPROFILE:-$HOME} ;; esac
  [ -n "$h" ] && p="${1/#"$h"/$t}"; s="${p//\\//}"
  case "$2" in
    base)  local b="${s%/}"; b="${b##*/}"; [ -n "$s" ] && printf %s "${b:-/}" ;;
    last2) local a="${s%/*}"; if [ "$a" = "$s" ]; then printf %s "$p"; else printf %s "${a##*/}/${s##*/}"; fi ;;
    full)  printf %s "$1" ;;
    *)     printf %s "$p" ;;
  esac; }
round(){ awk -v n="$1" 'BEGIN{ if(n=="") exit
  n=n+0; printf "%d", (n>=0 ? int(n+0.5) : -int(-n+0.5)) }'; }
strip_paren(){ printf %s "${1%% (*}"; }
spaces(){ local i out=""; for (( i=0; i<$1; i++ )); do out+=" "; done; printf %s "$out"; }
repeat_ch(){ local i out=""; for (( i=0; i<$2; i++ )); do out+="$1"; done; printf %s "$out"; }

# ---------- payload ----------
# lengths and cuts count characters only in a UTF-8 locale, which some setups leave out
_u='é'; [ ${#_u} = 1 ] || { for _l in C.UTF-8 en_US.UTF-8; do export LC_ALL=$_l; [ ${#_u} = 1 ] && break; done; [ ${#_u} = 1 ] || unset LC_ALL; } 2>/dev/null
input=$(cat)
# Fall back to an empty object if stdin is empty or not a JSON object,
# so a stray invocation prints a bare line instead of a jq error.
printf %s "$input" | jq -e 'type == "object"' >/dev/null 2>&1 || input='{}'
command -v jq >/dev/null 2>&1 || { printf %s 'This status line needs jq (jqlang.org). Install it, then restart Claude Code.'; exit 0; }
F=()
while IFS= read -r _l; do F+=("$_l"); done < <(printf %s "$input" | jq -r '
  ((try (.model.display_name // "Claude") catch "Claude") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_model_display_name
  ((try (.effort.level // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_effort_level
  ((try (.context_window.context_window_size // 200000) catch 200000) | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_context_window_context_window_size
  ((try (.cost.total_cost_usd // 0) catch 0) | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_cost_total_cost_usd
  ((try (.thinking.enabled // "false") catch "false") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_thinking_enabled
  ((try (.fast_mode // "false") catch "false") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_fast_mode
  ((try (.context_window.used_percentage // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_context_window_used_percentage
  ((try (.context_window.total_input_tokens // 0) catch 0) | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_context_window_total_input_tokens
  ((try (.context_window.current_usage.input_tokens // 0) catch 0) | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_context_window_current_usage_input_tokens
  ((try (.context_window.current_usage.output_tokens // 0) catch 0) | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_context_window_current_usage_output_tokens
  ((try (.rate_limits.five_hour.used_percentage // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_rate_limits_five_hour_used_percentage
  ((try (.rate_limits.five_hour.resets_at // 0) catch 0) | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_rate_limits_five_hour_resets_at
  ((try (.rate_limits.seven_day.used_percentage // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_rate_limits_seven_day_used_percentage
  ((try (.workspace.current_dir // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_workspace_current_dir
  ((try (.workspace.git_worktree // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_workspace_git_worktree
  ((try (.pr.number // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_pr_number
  ((try (.workspace.repo.owner // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end),   # F_workspace_repo_owner
  ((try (.workspace.repo.name // "") catch "") | if type == "object" or type == "array" then tojson elif type == "string" then gsub("[\r\n]"; " ") else . end)   # F_workspace_repo_name
' | tr -d '\r')
F_model_display_name=${F[0]}
F_effort_level=${F[1]}
F_context_window_context_window_size=${F[2]}
F_cost_total_cost_usd=${F[3]}
F_thinking_enabled=${F[4]}
F_fast_mode=${F[5]}
F_context_window_used_percentage=${F[6]}
F_context_window_total_input_tokens=${F[7]}
F_context_window_current_usage_input_tokens=${F[8]}
F_context_window_current_usage_output_tokens=${F[9]}
F_rate_limits_five_hour_used_percentage=${F[10]}
F_rate_limits_five_hour_resets_at=${F[11]}
F_rate_limits_seven_day_used_percentage=${F[12]}
F_workspace_current_dir=${F[13]}
F_workspace_git_worktree=${F[14]}
F_pr_number=${F[15]}
F_workspace_repo_owner=${F[16]}
F_workspace_repo_name=${F[17]}
GD=$(printf %s "$input" | jq -r '.workspace.current_dir // .cwd // ""' | tr -d '\r')

# ---------- segments ----------
A1L=()
P1L=()
v1l1="$(strip_paren "$F_model_display_name")"
if [ -n "$v1l1" ]; then
  A1L+=("${C_accent}󰚩 ${C_accent}${v1l1}${R}")
  P1L+=("󰚩 ${v1l1}")
fi
v1l2="$F_effort_level"
if [ -n "$v1l2" ]; then
  A1L+=("${C_special}󱅝 ${C_special}${v1l2}${R}")
  P1L+=("󱅝 ${v1l2}")
fi
v1l3="$(knum "$F_context_window_context_window_size")"
if [ -n "$v1l3" ]; then
  A1L+=("${C_dim}󰑭 ${C_dim}${v1l3}${R}")
  P1L+=("󰑭 ${v1l3}")
fi
v1l4="$(money "$F_cost_total_cost_usd" 'usd')"
if [ -n "$v1l4" ]; then
  A1L+=("${C_good} ${C_good}${v1l4}${R}")
  P1L+=(" ${v1l4}")
fi
v1l5="$(bool_map "$F_thinking_enabled" 'think' '')"
if [ -n "$v1l5" ]; then
  A1L+=("${C_good}󰟶 ${C_good}${v1l5}${R}")
  P1L+=("󰟶 ${v1l5}")
fi
v1l6="$(bool_map "$F_fast_mode" 'FAST' '')"
if [ -n "$v1l6" ]; then
  A1L+=("${C_warn} ${C_warn}${v1l6}${R}")
  P1L+=(" ${v1l6}")
fi

A2L=()
P2L=()
v2l1="$(round "$F_context_window_used_percentage")"
if [ -n "$v2l1" ]; then
  A2L+=("$(pct_color "$v2l1")󰧑 $(pct_color "$v2l1")${v2l1}$(pct_color "$v2l1")%${R}")
  P2L+=("󰧑 ${v2l1}%")
fi
v2l2="$(cat_ne "$(knum "$F_context_window_total_input_tokens")" "/" "$(knum "$F_context_window_context_window_size")")"
if [ -n "$v2l2" ]; then
  A2L+=("${C_muted}󰆙 ${C_muted}${v2l2}${R}")
  P2L+=("󰆙 ${v2l2}")
fi
v2l3="$(knum "$F_context_window_current_usage_input_tokens")"
if [ -n "$v2l3" ]; then
  A2L+=("${C_muted}󰜮 ${C_muted}${v2l3}${R}")
  P2L+=("󰜮 ${v2l3}")
fi
v2l4="$(knum "$F_context_window_current_usage_output_tokens")"
if [ -n "$v2l4" ]; then
  A2L+=("${C_muted}󰜷 ${C_muted}${v2l4}${R}")
  P2L+=("󰜷 ${v2l4}")
fi

A2R=()
P2R=()
v2r1="$(round "$F_rate_limits_five_hour_used_percentage")"
if [ -n "$v2r1" ]; then
  A2R+=("$(pct_color "$v2r1")󰔟 ${C_dim}5H $(pct_color "$v2r1")${v2r1}$(pct_color "$v2r1")%${R}")
  P2R+=("󰔟 5H ${v2r1}%")
fi
v2r2="$(time_left "$F_rate_limits_five_hour_resets_at")"
if [ -n "$v2r2" ]; then
  A2R+=("${C_muted}󰑐 ${C_muted}${v2r2}${R}")
  P2R+=("󰑐 ${v2r2}")
fi
v2r3="$(round "$F_rate_limits_seven_day_used_percentage")"
if [ -n "$v2r3" ]; then
  A2R+=("$(pct_color "$v2r3")󰨳 ${C_dim}7D $(pct_color "$v2r3")${v2r3}$(pct_color "$v2r3")%${R}")
  P2R+=("󰨳 7D ${v2r3}%")
fi

A3L=()
P3L=()
v3l1="$(short_path "$F_workspace_current_dir" 'base')"
if [ -n "$v3l1" ]; then
  A3L+=("${C_info} ${C_info}${v3l1}${R}")
  P3L+=(" ${v3l1}")
fi
v3l2="$(git_q 'branch')"
if [ -n "$v3l2" ]; then
  A3L+=("${C_special} ${C_special}${v3l2}${R}")
  P3L+=(" ${v3l2}")
fi
v3l3="$F_workspace_git_worktree"
if [ -n "$v3l3" ]; then
  A3L+=("${C_special}󰙅 ${C_special}${v3l3}${R}")
  P3L+=("󰙅 ${v3l3}")
fi
v3l4="$(cat_ne "#" "$F_pr_number")"
if [ -n "$v3l4" ]; then
  A3L+=("${C_info} ${C_info}${v3l4}${R}")
  P3L+=(" ${v3l4}")
fi
v3l5="$(cat_ne "$F_workspace_repo_owner" "/" "$F_workspace_repo_name")"
if [ -n "$v3l5" ]; then
  A3L+=("${C_muted} ${C_muted}${v3l5}${R}")
  P3L+=(" ${v3l5}")
fi

A3R=()
P3R=()
v3r1="$(basename_of "${VIRTUAL_ENV:-}")"
if [ -n "$v3r1" ]; then
  A3R+=("${C_good}󱔎 ${C_good}${v3r1}${R}")
  P3R+=("󱔎 ${v3r1}")
fi

# ---------- assemble ----------
SEP="${C_dim}  │  ${R}"
SEPP="  │  "
OUT1="$(join_seg "$SEP" "${A1L[@]}")"
BP1="$(join_seg "$SEPP" "${P1L[@]}")"
OUT2="$(join_seg "$SEP" "${A2L[@]}")  $(join_seg "$SEP" "${A2R[@]}")"
BP2="$(join_seg "$SEPP" "${P2L[@]}")  $(join_seg "$SEPP" "${P2R[@]}")"
OUT3="$(join_seg "$SEP" "${A3L[@]}")  $(join_seg "$SEP" "${A3R[@]}")"
BP3="$(join_seg "$SEPP" "${P3L[@]}")  $(join_seg "$SEPP" "${P3R[@]}")"

# ---------- output ----------
printf '%s\n%s\n%s' "$OUT1" "$OUT2" "$OUT3"
